#!/usr/bin/env bash
# Instalador da Pulso Treino para Ubuntu 22.04 / 24.04.
# Pode correr outra vez para atualizar: os dados e as contas mantêm-se.
set -euo pipefail
if [ "$(id -u)" -ne 0 ]; then exec sudo bash "$0" "$@"; fi

APP=/opt/pulso
DATA=/var/lib/pulso
ENVF=/etc/pulso.env
SELF="$(readlink -f "$0")"
say(){ printf '\n\033[1;33m==> %s\033[0m\n' "$*"; }
ok(){ printf '\033[1;32m%s\033[0m\n' "$*"; }
fail(){ printf '\n\033[1;31mERRO: %s\033[0m\n' "$*"; exit 1; }

say "A verificar o servidor"
if ss -ltnp 2>/dev/null | grep -E '[:.]443[[:space:]]' | grep -vq '"caddy"'; then
  fail "A porta 443 já está a ser usada por outro programa. Não mexi em nada."
fi
ok "Porta 443 livre. O painel dos robôs na porta 80 não é alterado."

IP="$(curl -4 -fsS --max-time 10 https://api.ipify.org || curl -4 -fsS --max-time 10 https://ifconfig.me || true)"
[[ "$IP" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || fail "Não consegui descobrir o IP público do servidor."
DOMAIN="pulso.${IP//./-}.sslip.io"
ok "Endereço da app: https://$DOMAIN"

say "A preparar a configuração do HTTPS"
mkdir -p /etc/caddy
if [ -f /etc/caddy/Caddyfile ] && ! grep -q "# pulso" /etc/caddy/Caddyfile; then
  cp /etc/caddy/Caddyfile "/etc/caddy/Caddyfile.antes-da-pulso.$(date +%s)"
fi
cat > /etc/caddy/Caddyfile <<EOF
# pulso — gerado pelo instalador
{
	auto_https disable_redirects
}

https://$DOMAIN {
	tls {
		issuer acme {
			disable_http_challenge
		}
	}
	encode gzip
	header Strict-Transport-Security "max-age=31536000"
	reverse_proxy 127.0.0.1:8090
}
EOF

say "A instalar programas (pode demorar uns minutos)"
export DEBIAN_FRONTEND=noninteractive
apt-get update -y -qq
apt-get install -y -qq python3 python3-venv curl ca-certificates gnupg debian-keyring debian-archive-keyring apt-transport-https >/dev/null
if ! command -v caddy >/dev/null 2>&1; then
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' | gpg --dearmor --yes -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' > /etc/apt/sources.list.d/caddy-stable.list
  apt-get update -y -qq
  apt-get install -y -qq -o Dpkg::Options::=--force-confold caddy >/dev/null
fi
ok "Programas instalados."

say "A instalar a Pulso"
id pulso >/dev/null 2>&1 || useradd --system --home-dir "$APP" --shell /usr/sbin/nologin pulso
mkdir -p "$APP" "$DATA"
rm -rf "$APP/static"
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$SELF" | tail -n +2 | base64 -d | tar xz -C "$APP"
chown -R root:root "$APP"; chown -R pulso:pulso "$DATA"; chmod 750 "$DATA"
[ -x "$APP/venv/bin/python" ] || python3 -m venv "$APP/venv"
"$APP/venv/bin/pip" install -q --upgrade pip >/dev/null
"$APP/venv/bin/pip" install -q "pywebpush==2.5.0" >/dev/null
KEY=""
[ -f "$ENVF" ] && KEY="$(grep -E '^ANTHROPIC_API_KEY=' "$ENVF" | cut -d= -f2- || true)"
cat > "$ENVF" <<EOF
PULSO_DATA=$DATA
PULSO_DOMAIN=$DOMAIN
PULSO_TZ=Europe/Lisbon
# Para ativar o coach com IA, cola aqui a tua chave da API da Anthropic e corre: sudo systemctl restart pulso
ANTHROPIC_API_KEY=$KEY
EOF
chown root:pulso "$ENVF"; chmod 640 "$ENVF"

cat > /etc/systemd/system/pulso.service <<EOF
[Unit]
Description=Pulso Treino
After=network-online.target
Wants=network-online.target

[Service]
User=pulso
Group=pulso
EnvironmentFile=$ENVF
WorkingDirectory=$APP
ExecStart=$APP/venv/bin/python $APP/app.py
Restart=always
RestartSec=3
NoNewPrivileges=yes
ProtectSystem=strict
ProtectHome=yes
PrivateTmp=yes
ReadWritePaths=$DATA

[Install]
WantedBy=multi-user.target
EOF
systemctl daemon-reload
systemctl enable -q pulso
systemctl restart pulso
sleep 2
curl -fsS --max-time 5 http://127.0.0.1:8090/api/health >/dev/null || fail "A Pulso não arrancou. Vê o erro com: journalctl -u pulso -n 50"
ok "Pulso a correr."

say "A ligar o HTTPS"
caddy validate --config /etc/caddy/Caddyfile --adapter caddyfile >/dev/null 2>&1 || fail "Configuração do Caddy inválida."
systemctl enable -q caddy
systemctl restart caddy
if command -v ufw >/dev/null 2>&1 && ufw status | grep -q "Status: active"; then ufw allow 443/tcp >/dev/null; ok "Porta 443 aberta na firewall do Ubuntu."; fi

N="$(runuser -u pulso -- env PULSO_DATA="$DATA" "$APP/venv/bin/python" "$APP/app.py" count)"
if [ "$N" = "0" ]; then
  say "Cria a tua conta de administrador"
  until runuser -u pulso -- env PULSO_DATA="$DATA" "$APP/venv/bin/python" "$APP/app.py" adduser --admin; do echo "Tenta outra vez."; done
fi

say "A pedir o certificado HTTPS (até 2 minutos)"
HTTPS_OK=0
for i in $(seq 1 24); do
  if curl -fsS --max-time 5 "https://$DOMAIN/api/health" >/dev/null 2>&1; then HTTPS_OK=1; break; fi
  sleep 5
done
echo
if [ "$HTTPS_OK" = "1" ]; then
  ok "============================================================"
  ok " Pulso pronta: https://$DOMAIN"
  ok "============================================================"
  echo " 1. Abre esse endereço no Chrome do Android e entra com a tua conta."
  echo " 2. Menu ⋮ > Adicionar ao ecrã principal (ou Instalar app)."
  echo " 3. Abre a Pulso pelo ícone > Perfil > Ativar notificações."
else
  printf '\033[1;31m%s\033[0m\n' "A app está instalada, mas o HTTPS ainda não responde em https://$DOMAIN"
  echo " Quase sempre é a firewall da Clouding: no painel, abre a porta TCP 443 (entrada)"
  echo " na firewall do servidor e espera 1 minuto. O certificado é pedido sozinho."
  echo " Para ver o que se passa: journalctl -u caddy -n 30"
fi
echo
echo " Contas: Perfil > Pessoas com acesso (só o administrador vê)."
echo " Coach com IA: sudo nano $ENVF  (ANTHROPIC_API_KEY=...) e depois sudo systemctl restart pulso"
echo " Os dados ficam em $DATA. Para atualizar a app, corre de novo um instalador novo."
exit 0
